BEGIN;
-- Insurance coverage annotates the original customer receivable; collections post through the existing settlement RPC.
CREATE SCHEMA erp_insurance_private;
REVOKE ALL ON SCHEMA erp_insurance_private FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE public.erp_insurance_companies(cafe_id uuid NOT NULL REFERENCES public.cafes(id),id uuid NOT NULL,number bigint GENERATED BY DEFAULT AS IDENTITY,name text NOT NULL CHECK(length(name) BETWEEN 1 AND 160),phone text NOT NULL DEFAULT '' CHECK(length(phone)<=30),email text NOT NULL DEFAULT '' CHECK(length(email)<=255),website text NOT NULL DEFAULT '' CHECK(length(website)<=500),active boolean NOT NULL DEFAULT true,revision integer NOT NULL DEFAULT 1,PRIMARY KEY(cafe_id,id),UNIQUE(cafe_id,name));
CREATE TABLE public.erp_insurance_classes(cafe_id uuid NOT NULL,id uuid NOT NULL,company_id uuid NOT NULL,name text NOT NULL CHECK(length(name) BETWEEN 1 AND 160),active boolean NOT NULL DEFAULT true,rules jsonb NOT NULL CHECK(jsonb_typeof(rules)='array'),revision integer NOT NULL DEFAULT 1,PRIMARY KEY(cafe_id,id),UNIQUE(cafe_id,company_id,name),UNIQUE(cafe_id,id,company_id),FOREIGN KEY(cafe_id,company_id) REFERENCES public.erp_insurance_companies(cafe_id,id));
CREATE TABLE public.erp_insurance_enrollments(cafe_id uuid NOT NULL,customer_id uuid NOT NULL,company_id uuid,class_id uuid,number text NOT NULL DEFAULT '' CHECK(length(number)<=100),revision integer NOT NULL DEFAULT 1,PRIMARY KEY(cafe_id,customer_id),CHECK((company_id IS NULL)=(class_id IS NULL)),FOREIGN KEY(cafe_id,customer_id) REFERENCES public.bf_parties(cafe_id,id),FOREIGN KEY(cafe_id,class_id,company_id) REFERENCES public.erp_insurance_classes(cafe_id,id,company_id));
CREATE TABLE public.erp_insurance_invoices(cafe_id uuid NOT NULL,id uuid NOT NULL,company_id uuid NOT NULL,class_id uuid NOT NULL,customer_id uuid NOT NULL,draft_id uuid NOT NULL,invoice_id uuid,rules_snapshot jsonb NOT NULL,line_rules jsonb NOT NULL,line_inputs jsonb NOT NULL,pricing_hash text NOT NULL,class_name text NOT NULL,insurance_number text NOT NULL,enrollment_revision integer NOT NULL,coverage jsonb,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(cafe_id,id),UNIQUE(cafe_id,draft_id),UNIQUE(cafe_id,invoice_id),FOREIGN KEY(cafe_id,class_id,company_id) REFERENCES public.erp_insurance_classes(cafe_id,id,company_id),FOREIGN KEY(cafe_id,customer_id) REFERENCES public.bf_parties(cafe_id,id),FOREIGN KEY(cafe_id,draft_id) REFERENCES public.bf_invoice_drafts(cafe_id,id),FOREIGN KEY(cafe_id,invoice_id) REFERENCES public.bf_documents(cafe_id,id));
CREATE TABLE public.erp_insurance_collections(cafe_id uuid NOT NULL,binding_id uuid NOT NULL,document_id uuid NOT NULL,payer text NOT NULL CHECK(payer IN('company','customer')),PRIMARY KEY(cafe_id,document_id),FOREIGN KEY(cafe_id,binding_id) REFERENCES public.erp_insurance_invoices(cafe_id,id),FOREIGN KEY(cafe_id,document_id) REFERENCES public.bf_documents(cafe_id,id));
CREATE TABLE public.erp_insurance_events(cafe_id uuid NOT NULL REFERENCES public.cafes(id),id uuid PRIMARY KEY DEFAULT gen_random_uuid(),record_id uuid NOT NULL,action text NOT NULL,actor uuid REFERENCES auth.users(id),at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE erp_insurance_private.requests(cafe_id uuid NOT NULL,request_id uuid NOT NULL,actor uuid NOT NULL,action text NOT NULL,input jsonb NOT NULL,result jsonb NOT NULL,PRIMARY KEY(cafe_id,request_id));
CREATE INDEX ON public.erp_insurance_invoices(cafe_id,company_id,created_at);
CREATE INDEX ON public.erp_insurance_invoices(cafe_id,customer_id);
CREATE INDEX ON public.erp_insurance_collections(cafe_id,binding_id);
DO $$DECLARE d text[];BEGIN d:=erp_access_private.domains();IF NOT('insurance'=ANY(d)) THEN d:=d||'insurance'::text;EXECUTE format('CREATE OR REPLACE FUNCTION erp_access_private.domains() RETURNS text[] LANGUAGE sql IMMUTABLE SET search_path='''' AS $f$SELECT %L::text[]$f$',d);END IF;END $$;
UPDATE public.erp_roles SET permissions=permissions||jsonb_build_object('insurance',jsonb_build_object('read',false,'create',false,'update',false,'delete',false,'approve',false,'settings',false,'files',false)) WHERE NOT(permissions?'insurance');
CREATE FUNCTION erp_insurance_private.authorize(c uuid,a text DEFAULT 'read') RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE r text;BEGIN r:=brand_finance_private.role_for(c);IF coalesce(r,'') NOT IN('owner','manager','accountant','auditor') OR(a<>'read' AND r='auditor') THEN RAISE EXCEPTION 'لا تملك صلاحية إدارة التأمين' USING ERRCODE='42501';END IF;PERFORM erp_access_private.assert_allowed(c,'insurance',a);RETURN r;END $$;
CREATE FUNCTION erp_insurance_private.pricing_hash(payload jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path='' AS $$SELECT md5(((payload->'invoice')-ARRAY['accountId','paymentKind','note','applyCredit','statusId','manualNumber'])::text)$$;
CREATE FUNCTION erp_insurance_private.categories(c uuid) RETURNS TABLE(id uuid,name text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$BEGIN
 RETURN QUERY SELECT m.id,m.name||' — القائمة' FROM public.menu_categories m WHERE m.cafe_id=c;
 IF to_regclass('public.erp_inventory_catalogs') IS NOT NULL THEN RETURN QUERY EXECUTE 'SELECT id,name||'' — المخزون'' FROM public.erp_inventory_catalogs WHERE cafe_id=$1 AND kind=''category'' AND active' USING c;END IF;
END $$;
CREATE FUNCTION erp_insurance_private.validate_rules(c uuid,rules jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE r jsonb;category text;cats text[]:='{}';ids text[]:='{}';all_count integer:=0;BEGIN
 IF jsonb_typeof(rules) IS DISTINCT FROM 'array' OR jsonb_array_length(rules) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'أضف قاعدة تغطية واحدة على الأقل';END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(rules) LOOP
  IF(r->>'id') IS NULL OR(r->>'id')=ANY(ids) OR jsonb_typeof(r->'categories') IS DISTINCT FROM 'array' OR jsonb_array_length(r->'categories')>100 THEN RAISE EXCEPTION 'راجع معرفات القواعد والتصنيفات';END IF;PERFORM(r->>'id')::uuid;ids:=ids||(r->>'id');
  IF(r->>'discount') IS NULL OR(r->>'companyShare') IS NULL OR(r->>'customerShare') IS NULL OR(r->>'discount')::numeric NOT BETWEEN 0 AND 100 OR(r->>'companyShare')::numeric NOT BETWEEN 0 AND 100 OR(r->>'customerShare')::numeric NOT BETWEEN 0 AND 100 OR(r->>'companyShare')::numeric+(r->>'customerShare')::numeric<>100 OR coalesce(r->>'capFor','') NOT IN('company','customer') OR(nullif(r->>'maxCopayment','') IS NOT NULL AND((r->>'maxCopayment')::numeric NOT BETWEEN 0 AND 1e9 OR(r->>'maxCopayment')::numeric<>round((r->>'maxCopayment')::numeric,2))) THEN RAISE EXCEPTION 'راجع نسب الخصم والتحمل والحد الأقصى';END IF;
  IF jsonb_array_length(r->'categories')=0 THEN all_count:=all_count+1;END IF;
  FOR category IN SELECT jsonb_array_elements_text(r->'categories') LOOP IF category=ANY(cats) OR NOT EXISTS(SELECT 1 FROM erp_insurance_private.categories(c) x WHERE x.id=category::uuid) THEN RAISE EXCEPTION 'التصنيف مكرر أو غير متاح';END IF;cats:=cats||category;END LOOP;
 END LOOP;IF all_count>1 THEN RAISE EXCEPTION 'أضف قاعدة عامة واحدة فقط';END IF;
END $$;
CREATE FUNCTION erp_insurance_private.collected(c uuid,b uuid,p text,exclude_source uuid DEFAULT NULL) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT coalesce(sum((brand_finance_private.payment_document(d)).total),0) FROM public.erp_insurance_collections x JOIN public.bf_documents d ON d.cafe_id=x.cafe_id AND d.id=x.document_id WHERE x.cafe_id=c AND x.binding_id=b AND x.payer=p AND(exclude_source IS NULL OR x.document_id<>exclude_source)$$;
CREATE FUNCTION erp_insurance_private.prepare(c uuid,draft uuid,rev integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
#variable_conflict use_variable
DECLARE d public.bf_invoice_drafts;e public.erp_insurance_enrollments;cl public.erp_insurance_classes;binding public.erp_insurance_invoices;line jsonb;inventory jsonb;old_input jsonb;rule jsonb;lines jsonb:='[]';line_rules jsonb:='[]';line_inputs jsonb:='[]';category uuid;product uuid;price numeric;qty numeric;gross numeric;discount numeric;manual_discount numeric;manual_kind text;next_discount numeric;payload jsonb;result jsonb;customer uuid;binding_id uuid;
BEGIN
 SELECT * INTO d FROM public.bf_invoice_drafts WHERE cafe_id=c AND id=draft FOR UPDATE;IF d.id IS NULL OR d.revision<>rev THEN RAISE EXCEPTION 'تغيرت مسودة الفاتورة' USING ERRCODE='40001';END IF;
 IF EXISTS(SELECT 1 FROM public.bf_company_invoices WHERE cafe_id=c AND draft_id=draft) THEN RAISE EXCEPTION 'لا يمكن تغيير فئة التأمين بعد إصدار الفاتورة';END IF;
 customer:=nullif(d.payload#>>'{invoice,partyId}','')::uuid;SELECT * INTO e FROM public.erp_insurance_enrollments WHERE cafe_id=c AND customer_id=customer;
 SELECT * INTO cl FROM public.erp_insurance_classes WHERE cafe_id=c AND id=e.class_id AND company_id=e.company_id AND active;IF cl.id IS NULL OR NOT EXISTS(SELECT 1 FROM public.erp_insurance_companies WHERE cafe_id=c AND id=e.company_id AND active) THEN RAISE EXCEPTION 'حدد شركة وفئة تأمين نشطة للعميل';END IF;
 IF coalesce(d.payload#>>'{invoice,currency}','SAR')<>'SAR' OR coalesce((d.payload#>>'{invoice,exchangeRate}')::numeric,1)<>1 THEN RAISE EXCEPTION 'تغطية التأمين متاحة لفاتورة بالريال السعودي';END IF;
 IF nullif(d.payload#>>'{invoice,adjustment,typeId}','') IS NOT NULL THEN RAISE EXCEPTION 'أزل تسوية الفاتورة الإضافية قبل حساب فئة التأمين';END IF;
 IF(SELECT count(DISTINCT value->>'key') FROM jsonb_array_elements(d.payload#>'{invoice,lines}'))<>jsonb_array_length(d.payload#>'{invoice,lines}') THEN RAISE EXCEPTION 'معرفات بنود الفاتورة مكررة أو مفقودة';END IF;
 SELECT * INTO binding FROM public.erp_insurance_invoices WHERE cafe_id=c AND draft_id=draft FOR UPDATE;
 FOR line IN SELECT value FROM jsonb_array_elements(d.payload#>'{invoice,lines}') LOOP
  product:=nullif(line->>'productId','')::uuid;category:=NULL;price:=nullif(line->>'price','')::numeric;qty:=(line->>'quantity')::numeric;
  IF product IS NOT NULL THEN IF line->>'catalogSource'='inventory' THEN IF to_regprocedure('erp_inventory_private.sale_item(uuid,uuid,text)') IS NULL THEN RAISE EXCEPTION 'محول أصناف المخزون غير متاح';END IF;EXECUTE 'SELECT erp_inventory_private.sale_item($1,$2,$3)' INTO inventory USING c,product,coalesce(line->>'unitName','');category:=(inventory->>'categoryId')::uuid;price:=coalesce(price,(inventory->>'price')::numeric);ELSE SELECT category_id,coalesce(price,p.price) INTO category,price FROM public.menu_products p WHERE p.cafe_id=c AND p.id=product AND p.deleted_at IS NULL;IF NOT FOUND THEN RAISE EXCEPTION 'صنف الفاتورة غير متاح';END IF;END IF;END IF;
  IF price IS NULL OR qty IS NULL OR price<0 OR price>1e9 OR qty<=0 OR qty>9999 THEN RAISE EXCEPTION 'راجع أسعار وكميات بنود الفاتورة';END IF;
  SELECT value INTO rule FROM jsonb_array_elements(cl.rules) WHERE(value->'categories')?category::text ORDER BY value->>'id' LIMIT 1;IF rule IS NULL THEN SELECT value INTO rule FROM jsonb_array_elements(cl.rules) WHERE jsonb_array_length(value->'categories')=0 LIMIT 1;END IF;
  SELECT value INTO old_input FROM jsonb_array_elements(coalesce(binding.line_inputs,'[]')) WHERE value->>'key'=line->>'key';manual_discount:=coalesce((line->>'discount')::numeric,0);manual_kind:=coalesce(line->>'discountKind','amount');
  IF old_input IS NOT NULL AND manual_kind='amount' AND manual_discount=(old_input->>'appliedDiscount')::numeric THEN manual_discount:=(old_input->>'manualDiscount')::numeric;manual_kind:=old_input->>'manualKind';END IF;
  gross:=round(price*qty,2);discount:=round(CASE WHEN manual_kind='percent' THEN gross*manual_discount/100 ELSE manual_discount END,2);IF discount<0 OR discount>gross THEN RAISE EXCEPTION 'خصم السطر يتجاوز قيمته';END IF;
  next_discount:=discount+round((gross-discount)*coalesce((rule->>'discount')::numeric,0)/100,2);
  lines:=lines||jsonb_build_array(line||jsonb_build_object('price',price,'discount',next_discount,'discountKind','amount'));
  line_rules:=line_rules||jsonb_build_array(jsonb_build_object('key',line->'key','ruleId',rule->>'id'));
  line_inputs:=line_inputs||jsonb_build_array(jsonb_build_object('key',line->'key','manualDiscount',manual_discount,'manualKind',manual_kind,'appliedDiscount',next_discount));
 END LOOP;
 payload:=jsonb_set(d.payload,'{invoice,lines}',lines);result:=public.brand_finance_save_invoice_draft(c,draft,rev,payload);binding_id:=coalesce(binding.id,gen_random_uuid());
 INSERT INTO public.erp_insurance_invoices(cafe_id,id,company_id,class_id,customer_id,draft_id,rules_snapshot,line_rules,line_inputs,pricing_hash,class_name,insurance_number,enrollment_revision,revision) VALUES(c,binding_id,e.company_id,e.class_id,customer,draft,cl.rules,line_rules,line_inputs,erp_insurance_private.pricing_hash(payload),cl.name,e.number,e.revision,coalesce(binding.revision,0)+1)
 ON CONFLICT(cafe_id,draft_id) DO UPDATE SET company_id=excluded.company_id,class_id=excluded.class_id,customer_id=excluded.customer_id,rules_snapshot=excluded.rules_snapshot,line_rules=excluded.line_rules,line_inputs=excluded.line_inputs,pricing_hash=excluded.pricing_hash,class_name=excluded.class_name,insurance_number=excluded.insurance_number,enrollment_revision=excluded.enrollment_revision,revision=excluded.revision;
 RETURN jsonb_build_object('id',binding_id,'draftId',draft,'revision',result->'revision');
END $$;
CREATE FUNCTION erp_insurance_private.invoice_issued() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE binding public.erp_insurance_invoices;payload jsonb;entry jsonb;rule jsonb;rule_id text;totals jsonb:='{}';groups jsonb:='[]';amount numeric;company numeric;customer numeric;company_total numeric:=0;customer_total numeric:=0;max_amount numeric;category_names text;idx integer:=0;
BEGIN
 SELECT * INTO binding FROM public.erp_insurance_invoices WHERE cafe_id=NEW.cafe_id AND draft_id=NEW.draft_id FOR UPDATE;IF NOT FOUND THEN RETURN NEW;END IF;
 SELECT d.payload INTO payload FROM public.bf_invoice_drafts d WHERE d.cafe_id=NEW.cafe_id AND d.id=NEW.draft_id;
 IF binding.pricing_hash<>erp_insurance_private.pricing_hash(payload) OR NOT EXISTS(SELECT 1 FROM public.erp_insurance_enrollments e WHERE e.cafe_id=NEW.cafe_id AND e.customer_id=binding.customer_id AND e.revision=binding.enrollment_revision AND e.class_id=binding.class_id) THEN RAISE EXCEPTION 'تغيرت بنود الفاتورة أو فئة العميل أعد حساب التأمين قبل الإصدار' USING ERRCODE='22023';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.erp_insurance_companies WHERE cafe_id=NEW.cafe_id AND id=binding.company_id AND active) THEN RAISE EXCEPTION 'شركة التأمين غير نشطة';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.erp_insurance_classes WHERE cafe_id=NEW.cafe_id AND id=binding.class_id AND active AND rules=binding.rules_snapshot) THEN RAISE EXCEPTION 'تغيرت قواعد الفئة أعد حساب التأمين قبل الإصدار';END IF;
 IF jsonb_array_length(binding.line_rules)<>jsonb_array_length(NEW.snapshot->'lines') THEN RAISE EXCEPTION 'عدد بنود التغطية لا يطابق الفاتورة';END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(NEW.snapshot->'lines') LOOP
  rule_id:=coalesce(binding.line_rules->idx->>'ruleId','uncovered');idx:=idx+1;amount:=(entry->>'total')::numeric;
  IF amount IS NULL OR amount<0 THEN RAISE EXCEPTION 'قيمة بند التأمين غير صالحة';END IF;
  totals:=jsonb_set(totals,ARRAY[rule_id],to_jsonb(coalesce((totals->>rule_id)::numeric,0)+amount));
 END LOOP;
 FOR rule_id,amount IN SELECT key,value::numeric FROM jsonb_each_text(totals) LOOP
  SELECT value INTO rule FROM jsonb_array_elements(binding.rules_snapshot) WHERE value->>'id'=rule_id;
  company:=round(amount*coalesce((rule->>'companyShare')::numeric,0)/100,2);customer:=amount-company;max_amount:=nullif(rule->>'maxCopayment','')::numeric;
  IF max_amount IS NOT NULL THEN IF rule->>'capFor'='company' THEN company:=least(company,max_amount);customer:=amount-company;ELSE customer:=least(customer,max_amount);company:=amount-customer;END IF;END IF;
  SELECT string_agg(name,' / ' ORDER BY name) INTO category_names FROM erp_insurance_private.categories(NEW.cafe_id) WHERE id::text IN(SELECT jsonb_array_elements_text(coalesce(rule->'categories','[]')));
  groups:=groups||jsonb_build_array(jsonb_build_object('ruleId',nullif(rule_id,'uncovered'),'label',CASE WHEN rule_id='uncovered' THEN 'غير مشمول' ELSE coalesce(category_names,'كل التصنيفات') END,'total',amount,'company',company,'customer',customer,'discount',coalesce(rule->'discount','0'::jsonb),'maxCopayment',max_amount,'capFor',coalesce(rule->>'capFor','customer')));company_total:=company_total+company;customer_total:=customer_total+customer;
 END LOOP;
 IF company_total+customer_total<>(NEW.snapshot->>'total')::numeric THEN RAISE EXCEPTION 'مجموع حصص التأمين لا يطابق إجمالي الفاتورة';END IF;
 UPDATE public.erp_insurance_invoices SET invoice_id=NEW.document_id,coverage=jsonb_build_object('total',company_total+customer_total,'company',company_total,'customer',customer_total,'groups',groups),revision=revision+1 WHERE cafe_id=NEW.cafe_id AND id=binding.id;
 INSERT INTO public.erp_insurance_events(cafe_id,record_id,action,actor) VALUES(NEW.cafe_id,binding.id,'invoice_issued',auth.uid());RETURN NEW;
END $$;
CREATE TRIGGER erp_insurance_invoice_issued BEFORE INSERT ON public.bf_company_invoices FOR EACH ROW EXECUTE FUNCTION erp_insurance_private.invoice_issued();
CREATE FUNCTION erp_insurance_private.payment_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE link public.erp_insurance_collections;b public.erp_insurance_invoices;amount numeric;maximum numeric;BEGIN
 SELECT * INTO link FROM public.erp_insurance_collections WHERE cafe_id=NEW.cafe_id AND document_id=NEW.source_id;IF NOT FOUND THEN RETURN NEW;END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.cafe_id::text,60412));SELECT * INTO b FROM public.erp_insurance_invoices WHERE cafe_id=NEW.cafe_id AND id=link.binding_id;
 amount:=CASE WHEN NEW.status='completed' THEN(NEW.payload->>'amount')::numeric ELSE 0 END;maximum:=(b.coverage->>link.payer)::numeric;
 IF amount+erp_insurance_private.collected(NEW.cafe_id,b.id,link.payer,NEW.source_id)>maximum THEN RAISE EXCEPTION 'تعديل الدفعة يتجاوز حصة الجهة الدافعة المتفق عليها';END IF;RETURN NEW;
END $$;
CREATE TRIGGER erp_insurance_payment_guard BEFORE INSERT OR UPDATE ON public.bf_invoice_payments FOR EACH ROW EXECUTE FUNCTION erp_insurance_private.payment_guard();
CREATE FUNCTION public.erp_insurance_read(p_cafe uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE role text;BEGIN role:=erp_insurance_private.authorize(p_cafe);RETURN jsonb_build_object(
 'companies',coalesce((SELECT jsonb_agg(to_jsonb(c)-'cafe_id' ORDER BY name) FROM public.erp_insurance_companies c WHERE cafe_id=p_cafe),'[]'::jsonb),
 'classes',coalesce((SELECT jsonb_agg((to_jsonb(c)-'cafe_id'-'company_id')||jsonb_build_object('companyId',company_id) ORDER BY name) FROM public.erp_insurance_classes c WHERE cafe_id=p_cafe),'[]'::jsonb),
 'enrollments',coalesce((SELECT jsonb_agg(jsonb_build_object('customerId',customer_id,'companyId',company_id,'classId',class_id,'number',number,'revision',revision)) FROM public.erp_insurance_enrollments WHERE cafe_id=p_cafe),'[]'::jsonb),
 'customers',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'phone',phone,'active',active) ORDER BY name) FROM public.bf_parties WHERE cafe_id=p_cafe AND kind='customer'),'[]'::jsonb),
 'categories',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name) ORDER BY name) FROM erp_insurance_private.categories(p_cafe)),'[]'::jsonb),
 'drafts',coalesce((SELECT jsonb_agg(jsonb_build_object('id',d.id,'revision',d.revision,'customerId',d.payload#>>'{invoice,partyId}','title',coalesce(d.payload#>>'{invoice,note}','مسودة فاتورة'))) FROM public.bf_invoice_drafts d WHERE d.cafe_id=p_cafe AND NOT EXISTS(SELECT 1 FROM public.bf_company_invoices i WHERE i.cafe_id=p_cafe AND i.draft_id=d.id)),'[]'::jsonb),
 'invoices',coalesce((SELECT jsonb_agg(jsonb_build_object('id',b.id,'revision',b.revision,'companyId',b.company_id,'classId',b.class_id,'customerId',b.customer_id,'draftId',b.draft_id,'invoiceId',b.invoice_id,'number',coalesce(e.display_number,d.number::text),'className',b.class_name,'insuranceNumber',b.insurance_number,'coverage',b.coverage,'companyCollected',erp_insurance_private.collected(p_cafe,b.id,'company'),'customerCollected',erp_insurance_private.collected(p_cafe,b.id,'customer'),'outstanding',coalesce((brand_finance_private.document_state(p_cafe,b.invoice_id)->>'outstanding')::numeric,0),'refunded',coalesce((brand_finance_private.document_state(p_cafe,b.invoice_id)->>'refunded_total')::numeric,0),'createdAt',b.created_at) ORDER BY b.created_at DESC) FROM public.erp_insurance_invoices b LEFT JOIN public.bf_documents d ON d.cafe_id=b.cafe_id AND d.id=b.invoice_id LEFT JOIN public.bf_invoice_extensions e ON e.cafe_id=b.cafe_id AND e.document_id=b.invoice_id WHERE b.cafe_id=p_cafe),'[]'::jsonb),
 'accounts',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name) ORDER BY name) FROM public.bf_accounts WHERE cafe_id=p_cafe AND active AND kind IN('cash','bank','pos') AND NOT is_cashier_drawer),'[]'::jsonb),
 'canCreate',role<>'auditor' AND erp_access_private.allowed(p_cafe,'insurance','create'),'canUpdate',role<>'auditor' AND erp_access_private.allowed(p_cafe,'insurance','update'),'canDelete',role<>'auditor' AND erp_access_private.allowed(p_cafe,'insurance','delete'),'canFiles',role<>'auditor' AND erp_access_private.allowed(p_cafe,'insurance','files'),'canApprove',role<>'auditor' AND erp_access_private.allowed(p_cafe,'insurance','approve'));
END $$;
CREATE FUNCTION public.erp_insurance_write(p_cafe uuid,p_action text,p_input jsonb,p_request uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE i uuid;rev integer;old_rev integer;prior erp_insurance_private.requests;result jsonb;cl public.erp_insurance_classes;b public.erp_insurance_invoices;amount numeric;maximum numeric;payer text;document uuid;company uuid;customer uuid;
BEGIN
 IF p_request IS NULL OR jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR octet_length(p_input::text)>100000 OR p_action NOT IN('company','class','enrollment','company_delete','class_delete','prepare','collect','unlink') THEN RAISE EXCEPTION 'الإجراء غير صالح';END IF;
 rev:=coalesce((p_input->>'revision')::integer,0);PERFORM erp_insurance_private.authorize(p_cafe,CASE WHEN p_action='collect' THEN 'approve' WHEN p_action LIKE '%_delete' OR p_action='unlink' THEN 'delete' WHEN p_action='prepare' THEN 'create' WHEN rev=0 THEN 'create' ELSE 'update' END);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,67953));
 SELECT * INTO prior FROM erp_insurance_private.requests WHERE cafe_id=p_cafe AND request_id=p_request;IF FOUND THEN IF prior.actor<>auth.uid() OR prior.action<>p_action OR prior.input<>p_input THEN RAISE EXCEPTION 'معرف العملية مستخدم لبيانات أخرى';END IF;RETURN prior.result;END IF;
 i:=nullif(p_input->>'id','')::uuid;
 IF p_action IN('company','company_delete') THEN
  SELECT revision INTO old_rev FROM public.erp_insurance_companies WHERE cafe_id=p_cafe AND id=i FOR UPDATE;IF coalesce(old_rev,0)<>rev THEN RAISE EXCEPTION 'تغيرت شركة التأمين' USING ERRCODE='40001';END IF;
  IF p_action='company_delete' THEN DELETE FROM public.erp_insurance_companies WHERE cafe_id=p_cafe AND id=i;IF NOT FOUND THEN RAISE EXCEPTION 'الشركة غير متاحة';END IF;
  ELSE
   IF jsonb_typeof(p_input->'active') IS DISTINCT FROM 'boolean' OR(coalesce(p_input->>'email','')<>'' AND(p_input->>'email')!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') OR(coalesce(p_input->>'website','')<>'' AND(p_input->>'website')!~'^https?://[^[:space:]]+$') THEN RAISE EXCEPTION 'راجع البريد والموقع وحالة الشركة';END IF;
   INSERT INTO public.erp_insurance_companies(cafe_id,id,name,phone,email,website,active,revision) VALUES(p_cafe,i,btrim(p_input->>'name'),coalesce(p_input->>'phone',''),coalesce(p_input->>'email',''),coalesce(p_input->>'website',''),(p_input->>'active')::boolean,rev+1) ON CONFLICT(cafe_id,id) DO UPDATE SET name=excluded.name,phone=excluded.phone,email=excluded.email,website=excluded.website,active=excluded.active,revision=excluded.revision;
  END IF;
 ELSIF p_action IN('class','class_delete') THEN
  SELECT * INTO cl FROM public.erp_insurance_classes WHERE cafe_id=p_cafe AND id=i FOR UPDATE;IF coalesce(cl.revision,0)<>rev THEN RAISE EXCEPTION 'تغيرت فئة التأمين' USING ERRCODE='40001';END IF;
  IF p_action='class_delete' THEN DELETE FROM public.erp_insurance_classes WHERE cafe_id=p_cafe AND id=i;IF NOT FOUND THEN RAISE EXCEPTION 'الفئة غير متاحة';END IF;
  ELSE
   company:=(p_input->>'companyId')::uuid;IF NOT EXISTS(SELECT 1 FROM public.erp_insurance_companies WHERE cafe_id=p_cafe AND id=company AND active) OR(cl.id IS NOT NULL AND cl.company_id<>company) OR jsonb_typeof(p_input->'active') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'شركة التأمين غير متاحة أو تغيرت';END IF;
   PERFORM erp_insurance_private.validate_rules(p_cafe,p_input->'rules');
   INSERT INTO public.erp_insurance_classes(cafe_id,id,company_id,name,active,rules,revision) VALUES(p_cafe,i,company,btrim(p_input->>'name'),(p_input->>'active')::boolean,p_input->'rules',rev+1) ON CONFLICT(cafe_id,id) DO UPDATE SET name=excluded.name,active=excluded.active,rules=excluded.rules,revision=excluded.revision;
  END IF;
 ELSIF p_action='enrollment' THEN
  customer:=(p_input->>'customerId')::uuid;i:=customer;IF NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=p_cafe AND id=customer AND kind='customer' AND active) THEN RAISE EXCEPTION 'العميل غير متاح';END IF;
  SELECT revision INTO old_rev FROM public.erp_insurance_enrollments WHERE cafe_id=p_cafe AND customer_id=customer FOR UPDATE;IF coalesce(old_rev,0)<>rev THEN RAISE EXCEPTION 'تغير تأمين العميل' USING ERRCODE='40001';END IF;
  company:=nullif(p_input->>'companyId','')::uuid;
  IF company IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.erp_insurance_classes x JOIN public.erp_insurance_companies c ON c.cafe_id=x.cafe_id AND c.id=x.company_id WHERE x.cafe_id=p_cafe AND x.id=(p_input->>'classId')::uuid AND x.company_id=company AND x.active AND c.active) THEN RAISE EXCEPTION 'شركة أو فئة التأمين غير متاحة';END IF;
  INSERT INTO public.erp_insurance_enrollments VALUES(p_cafe,customer,company,nullif(p_input->>'classId','')::uuid,coalesce(p_input->>'number',''),rev+1) ON CONFLICT(cafe_id,customer_id) DO UPDATE SET company_id=excluded.company_id,class_id=excluded.class_id,number=excluded.number,revision=excluded.revision;
 ELSIF p_action='prepare' THEN result:=erp_insurance_private.prepare(p_cafe,(p_input->>'draftId')::uuid,rev);i:=(result->>'id')::uuid;
 ELSIF p_action='unlink' THEN
  SELECT * INTO b FROM public.erp_insurance_invoices WHERE cafe_id=p_cafe AND id=i FOR UPDATE;IF b.id IS NULL OR b.revision<>rev THEN RAISE EXCEPTION 'تغير ربط التأمين' USING ERRCODE='40001';END IF;IF b.invoice_id IS NOT NULL THEN RAISE EXCEPTION 'لا يمكن تغيير فئة التأمين بعد إصدار الفاتورة';END IF;DELETE FROM public.erp_insurance_invoices WHERE cafe_id=p_cafe AND id=i;
 ELSIF p_action='collect' THEN
  SELECT * INTO b FROM public.erp_insurance_invoices WHERE cafe_id=p_cafe AND id=i FOR UPDATE;IF b.invoice_id IS NULL OR b.coverage IS NULL THEN RAISE EXCEPTION 'أصدر الفاتورة قبل التحصيل';END IF;
  payer:=p_input->>'payer';amount:=(p_input->>'amount')::numeric;IF coalesce(payer,'') NOT IN('company','customer') OR amount IS NULL OR amount<=0 OR amount>1e9 OR amount<>round(amount,2) THEN RAISE EXCEPTION 'راجع الجهة الدافعة ومبلغ التحصيل';END IF;
  maximum:=least((b.coverage->>payer)::numeric-erp_insurance_private.collected(p_cafe,b.id,payer),(brand_finance_private.document_state(p_cafe,b.invoice_id)->>'outstanding')::numeric);
  IF amount>maximum OR coalesce((brand_finance_private.document_state(p_cafe,b.invoice_id)->>'refunded_total')::numeric,0)>0 THEN RAISE EXCEPTION 'التحصيل يتجاوز الحصة المتفق عليها أو المتبقي على الفاتورة';END IF;
  result:=public.brand_finance_execute(p_cafe,'settlement',jsonb_build_object('documentId',b.invoice_id,'accountId',p_input->>'accountId','amount',amount,'note',left(CASE WHEN payer='company' THEN 'تحصيل حصة شركة التأمين '||(SELECT name FROM public.erp_insurance_companies WHERE cafe_id=p_cafe AND id=b.company_id) ELSE 'تحصيل حصة العميل' END||' — '||coalesce(p_input->>'note',''),1000)),p_request);
  document:=(result->>'id')::uuid;IF NOT EXISTS(SELECT 1 FROM public.bf_documents WHERE cafe_id=p_cafe AND id=document AND kind='settlement' AND reference_id=b.invoice_id) THEN RAISE EXCEPTION 'لم يثبت التحصيل على فاتورة المالية';END IF;
  INSERT INTO public.erp_insurance_collections VALUES(p_cafe,b.id,document,payer);result:=jsonb_build_object('id',b.id,'paymentId',document);
 END IF;
 result:=coalesce(result,jsonb_build_object('id',i,'revision',rev+1,'deleted',p_action LIKE '%_delete' OR p_action='unlink'));
 INSERT INTO public.erp_insurance_events(cafe_id,record_id,action,actor) VALUES(p_cafe,i,p_action,auth.uid());INSERT INTO erp_insurance_private.requests VALUES(p_cafe,p_request,auth.uid(),p_action,p_input,result);RETURN result;
END $$;
ALTER FUNCTION erp_file_private.assert_record(uuid,text,uuid,boolean) RENAME TO assert_record_before_insurance;
CREATE FUNCTION erp_file_private.assert_record(p_cafe uuid,p_type text,p_record uuid,p_write boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE present boolean;BEGIN
 IF p_type<>'insurance_company' THEN PERFORM erp_file_private.assert_record_before_insurance(p_cafe,p_type,p_record,p_write);RETURN;END IF;
 PERFORM erp_insurance_private.authorize(p_cafe,CASE WHEN p_write THEN 'files' ELSE 'read' END);
 IF p_write THEN SELECT true INTO present FROM public.erp_insurance_companies WHERE cafe_id=p_cafe AND id=p_record FOR KEY SHARE;ELSE SELECT EXISTS(SELECT 1 FROM public.erp_insurance_companies WHERE cafe_id=p_cafe AND id=p_record) INTO present;END IF;
 IF NOT coalesce(present,false) THEN RAISE EXCEPTION 'شركة التأمين غير متاحة' USING ERRCODE='42501';END IF;
END $$;
REVOKE ALL ON FUNCTION erp_file_private.assert_record(uuid,text,uuid,boolean),erp_file_private.assert_record_before_insurance(uuid,text,uuid,boolean) FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER erp_insurance_file_orphan_guard BEFORE DELETE ON public.erp_insurance_companies FOR EACH ROW EXECUTE FUNCTION erp_file_private.prevent_orphans('insurance_company');
ALTER FUNCTION erp_access_private.file_domain(text) RENAME TO file_domain_before_insurance;
CREATE FUNCTION erp_access_private.file_domain(p_type text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path='' AS $$SELECT CASE WHEN p_type='insurance_company' THEN 'insurance' ELSE erp_access_private.file_domain_before_insurance(p_type) END$$;
REVOKE ALL ON FUNCTION erp_access_private.file_domain(text),erp_access_private.file_domain_before_insurance(text) FROM PUBLIC,anon,authenticated,service_role;
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['erp_insurance_companies','erp_insurance_classes','erp_insurance_enrollments','erp_insurance_invoices','erp_insurance_collections','erp_insurance_events'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated,service_role',t);END LOOP;END $$;
ALTER TABLE erp_insurance_private.requests ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION erp_insurance_private.immutable_audit() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$BEGIN RAISE EXCEPTION 'سجل التدقيق والطلبات المؤكدة غير قابل للتعديل أو الحذف' USING ERRCODE='42501';END $$;
CREATE TRIGGER erp_insurance_events_immutable BEFORE UPDATE OR DELETE ON public.erp_insurance_events FOR EACH ROW EXECUTE FUNCTION erp_insurance_private.immutable_audit();
CREATE TRIGGER erp_insurance_requests_immutable BEFORE UPDATE OR DELETE ON erp_insurance_private.requests FOR EACH ROW EXECUTE FUNCTION erp_insurance_private.immutable_audit();
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA erp_insurance_private FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON ALL TABLES IN SCHEMA erp_insurance_private FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.erp_insurance_read(uuid),public.erp_insurance_write(uuid,text,jsonb,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.erp_insurance_read(uuid),public.erp_insurance_write(uuid,text,jsonb,uuid) TO authenticated;
NOTIFY pgrst,'reload schema';
COMMIT;
